// Real local socket faults; service and engine faults remain separate controls.
async fn local_ws_disarm(service:&mut Service,c:&Client,n:&Native){
 let path=n.root.join("capture-first-loss");if path.is_file(){fixture_input_remove(path).unwrap();}
 wait(service,c,"acknowledged expected local transport outage",5,|_|native_activity(n)["loss_monitor_armed"]==false).await;
}
#[test]#[ignore="Serial real WebSocket/native/Core/Server recovery, isolated credentials and disposable schema"]
fn local_ws_outage_and_app_restart_retains_game(){std::thread::Builder::new().name("local-ws-recovery".into()).stack_size(16*1024*1024).spawn(||tauri::async_runtime::block_on(async{
 let own=repo().join("spikes/noita-entry/.build/local-ws-client-20261101").join(format!("recovery-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&own).unwrap();eprintln!("LOCAL_WS_RECOVERY {}",own.display());
 let mut service=Service::start(&own);network_profile::enable_elapsed_clock(&mut service,&own);let router=PipeHarness::new();
 let mut client=Client::start(&service.private(),&own.join("host"),None,false,true,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;bundle(&mut service,&client).await;let mut native=Native::start(&client,None,false);wait(&mut service,&client,"local WS host Ready",30,|v|current_state_is(v,"Ready")&&native.root.join("associated").is_file()).await;let world=client.handle.view()["rejoin"]["current_world"].clone();
 service.command(json!({"op":"peer"}));let mut peer=Client::start(&service.private(),&own.join("peer"),None,true,true,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;bundle(&mut service,&peer).await;let mut sam=Native::start(&peer,None,false);wait(&mut service,&peer,"local WS peer Ready",30,|v|current_state_is(v,"Ready")&&sam.root.join("associated").is_file()).await;let peer_world=peer.handle.view()["rejoin"]["current_world"].clone();two_peer_ghost_with_start(&mut service,&client,&native,&world,&peer,&sam,&peer_world,"startReviewed").await;
 fixture_input_write(sam.root.join("unaffected-check"),b"peer unaffected by local socket and app restart").unwrap();local_ws_disarm(&mut service,&client,&native).await;
 let original=native_activity(&native);let process=native.child.id();let owner=native.owner;let generation=client.local_bridge().view()["listener"]["generation"].as_u64().unwrap();client.local_bridge().outage(true);
 let until=Instant::now()+Duration::from_secs(6);while Instant::now()<until{service.wall_clock();assert_peer_healthy(&peer,&sam);assert!(native.child.try_wait().unwrap().is_none());assert!(!matches!(client.handle.view()["connection"]["state"].as_str(),Some("Offline"|"Ended")));tokio::time::sleep(Duration::from_millis(100)).await;}
 assert_eq!(native_activity(&native)["protected"],true,"Socket loss did not hold the native world");client.local_bridge().outage(false);ready_owner(&mut service,&client,&native,&world,true).await;fresh_bidirectional_ghosts(&mut service,&client,&native,&peer,&sam,"local WS reconnect restores fresh paired ghosts").await;assert_eq!(native.owner,owner);assert!(client.local_bridge().view()["listener"]["generation"].as_u64().unwrap()>generation);assert_eq!(native_activity(&native)["seed_calls"],original["seed_calls"]);checkpoint(&own,"local-ws-loss-protection-and-automatic-same-world-recovery");
 local_ws_disarm(&mut service,&client,&native).await;let config=client.root.clone();let store=client.store.clone();client.close().await;
 // Reopen the same owned app configuration/journals and installation, exactly
 // as a real app restart does; the running DLL images are never overwritten.
 let mut restarted=Client::start(&service.private(),&config,Some(store),false,false,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;
 let until=Instant::now()+Duration::from_secs(10);native.owner=loop{service.wall_clock();assert_peer_healthy(&peer,&sam);if let Some(owner)=restarted.local_bridge().owner(){break owner}assert!(Instant::now()<until,"Retained native did not authenticate to restarted app: {}",restarted.local_bridge().view());tokio::time::sleep(Duration::from_millis(100)).await;};assert_ne!(native.owner,owner);assert_eq!(native.child.id(),process);
 native.view=restarted.handle.clone();for watch in service.watches.lock().unwrap().iter_mut(){if Arc::ptr_eq(&watch.child.0,&native.child.0){watch.view=restarted.handle.clone();}}
 // A retained fresh world has no Continue UI. Exercise the existing desktop
 // Rejoin action when the cold app's current intent requires that choice.
 wait(&mut service,&restarted,"existing cold-app consent projection",20,|v|matches!(v["connection"]["state"].as_str(),Some("Choice"|"Playing"|"Ready"))).await;
 if restarted.handle.view()["connection"]["state"]=="Choice"{restarted.handle.command(|c|Box::pin(async move{c.rejoin_previous()?;Ok(Value::Null)})).await.unwrap();}
 ready_owner(&mut service,&restarted,&native,&world,true).await;fresh_bidirectional_ghosts(&mut service,&restarted,&native,&peer,&sam,"retained game after app restart restores paired ghosts").await;assert_eq!(native_activity(&native)["seed_calls"],original["seed_calls"]);assert_eq!(native.child.id(),process);checkpoint(&own,"app-restart-rotated-capability-retained-native-world-and-seed");
 local_ws_disarm(&mut service,&restarted,&native).await;service.command(json!({"op":"transport","kind":"http","enabled":true,"target":"consumer"}));let until=Instant::now()+Duration::from_secs(16);while Instant::now()<until{service.wall_clock();assert_peer_healthy(&peer,&sam);assert!(!matches!(restarted.handle.view()["connection"]["state"].as_str(),Some("Offline"|"Ended")));tokio::time::sleep(Duration::from_millis(200)).await;}service.command(json!({"op":"transport","kind":"http","enabled":false,"target":"consumer"}));ready_owner(&mut service,&restarted,&native,&world,true).await;fresh_bidirectional_ghosts(&mut service,&restarted,&native,&peer,&sam,"HTTP recovery independent of local WS").await;
 wss_only_preserves_permission(&mut service,&restarted,&native,&peer,&sam).await;
 let result=json!({"passed":true,"actualNoita":false,"engineInputsInjected":true,"realWebSocketNativeCoreServer":true,"localWs":restarted.local_bridge().view(),"localLossRecovered":true,"appRestartSameNativeProcess":true,"sameWorld":world,"sameSeed":true,"httpAndInternetWssFaultsSeparate":true,"peerUnaffected":true});std::fs::write(own.join("results.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();native.close();sam.close();restarted.close().await;peer.close().await;service.close();
})).unwrap().join().unwrap();}
